#ifndef GGML_QUANT_CAPS_H
#define GGML_QUANT_CAPS_H

#include "ggml.h"

#ifdef __cplusplus
extern "C" {
#endif

// Semantic capabilities for quant types.
// Queried by kv-cache, graph, and attention code instead of hardcoding type checks.
// Default (unset) for all fields = false/0, meaning upstream types need no special handling.
struct ggml_quant_caps {
    // WHT rotation family: turbo2/3/4, planar3/4, iso3/4
    // True if this type uses Hadamard rotation infrastructure and needs head_dim alignment.
    bool     needs_wht;

    // Turbo family only: turbo2/3/4
    // True if this type participates in turbo-specific V adaptive layer modes (5/6/7).
    bool     turbo_family;

    // Deferred allocation: planar3/4, iso3/4
    // True if K cache should allocate as F16 during prefill, then convert to target type post-prefill.
    bool     needs_deferred;

    // Cache capabilities
    bool     k_cache_capable;
    bool     v_cache_capable;

    // Weight quantization
    bool     weight_capable;

    // Required head_dim alignment (0 = any alignment OK, 128 = must be multiple of 128)
    uint32_t head_align;
};

// Returns capabilities for a given type. Never returns NULL.
// For types with no caps entry, all fields are false/0 (safe default).
GGML_API const struct ggml_quant_caps * ggml_get_quant_caps(enum ggml_type type);

// Convenience predicates (inline, header-only):
static inline bool ggml_type_needs_wht(enum ggml_type type) {
    return ggml_get_quant_caps(type)->needs_wht;
}

static inline bool ggml_type_needs_deferred(enum ggml_type type) {
    return ggml_get_quant_caps(type)->needs_deferred;
}

static inline bool ggml_type_is_turbo_family(enum ggml_type type) {
    return ggml_get_quant_caps(type)->turbo_family;
}

static inline uint32_t ggml_type_head_align(enum ggml_type type) {
    return ggml_get_quant_caps(type)->head_align;
}

#ifdef __cplusplus
}
#endif

#endif // GGML_QUANT_CAPS_H

