        .turbo_family    = true,
        .k_cache_capable = true,
        .v_cache_capable = true,
        .head_align      = 128,
    },
    [GGML_TYPE_TURBO4_0] = {
        .needs_wht       = true,
        .turbo_family    = true,
        .k_cache_capable = true,
        .v_cache_capable = true,
        .head_align      = 128,
    },
    [GGML_TYPE_TURBO2_0] = {
        .needs_wht       = true,
        .turbo_family    = true,
        .k_cache_capable = true,
        .v_cache_capable = true,
        .head_align      = 128,
    },

    // === PlanarQuant family (planar3/4) ===
    // WHT rotation + deferred F16→quant allocation
    // NOTE: add these entries AFTER porting the quant implementations in Phase 4
    // [GGML_TYPE_PLANAR3_0] = {
    //     .needs_wht       = true,
    //     .turbo_family    = false,
    //     .needs_deferred  = true,
    //     .k_cache_capable = true,
    //     .v_cache_capable = true,
    //     .head_align      = 128,
    // },

    // === IsoQuant family (iso3/4) ===
    // WHT rotation (quaternion) + deferred F16→quant allocation
    // NOTE: add these entries AFTER porting the quant implementations in Phase 4
    // [GGML_TYPE_ISO3_0] = { ... same as planar ... },
};

const struct ggml_quant_caps * ggml_get_quant_caps(enum ggml_type type) {
    GGML_ASSERT(type >= 0 && type < GGML_TYPE_COUNT);
    return &quant_caps_table[type];
}

